package main

// All values and labels in these examples are synthetic. Consumers own data
// collection, permissions and persistence; the shared library only renders.
type chartExample struct {
	ID, Title, Description, Spec string
	Headers                      []string
	Rows                         [][]string
}

func advancedCharts() []chartExample {
	return []chartExample{
		{ID: "mixed-latency", Title: "Counts and response time", Description: "Independent left/right units; response-time line stays unstacked", Spec: `{"type":"bar","stacked":true,"legend":{"show":true},"domain":{"type":"time","min":"2026-01-01T00:00:00Z","max":"2026-01-01T00:10:00Z"},"axes":[{"id":"count","unit":"count","min":0,"max":100,"splitNumber":5},{"id":"latency","unit":"ms","position":"right","min":0,"max":10,"splitNumber":5,"alignTicks":true}],"datasets":[{"label":"Success","axis":"count","stack":"counts","data":[[1767225600000,30],[1767225660000,45],[1767226200000,60]],"backgroundColor":"#58a6ff"},{"label":"Errors","axis":"count","stack":"counts","data":[[1767225600000,2],[1767225660000,1],[1767226200000,3]],"backgroundColor":"#fb7185"},{"label":"Response time","type":"line","axis":"latency","stack":false,"data":[[1767225600000,3],[1767225660000,null],[1767226200000,6]],"borderColor":"#fbbf24"}]}`, Headers: []string{"UTC time", "Success", "Errors", "Response time"}, Rows: [][]string{{"00:00", "30", "2", "3 ms"}, {"00:01", "45", "1", "Unavailable"}, {"00:10", "60", "3", "6 ms"}}},
		{ID: "grouped-rates", Title: "Grouped upstream rates and latency", Description: "Click a legend to toggle both series for one synthetic upstream", Spec: `{"type":"line","domain":{"type":"time"},"legend":{"show":true},"axes":[{"id":"rate","unit":"qps","precision":2},{"id":"latency","unit":"us","position":"right","precision":1}],"datasets":[{"label":"Rate","legendGroup":"a","legendLabel":"Upstream A","axis":"rate","data":[[1767225600000,1.5],[1767225660000,null],[1767226200000,4.25]],"borderColor":"#58a6ff"},{"label":"Latency","legendGroup":"a","legendLabel":"Upstream A","axis":"latency","data":[[1767225600000,300],[1767225660000,350],[1767226200000,500]],"borderColor":"#93c5fd"},{"label":"Rate","legendGroup":"b","legendLabel":"Upstream B","axis":"rate","data":[[1767225600000,2],[1767225660000,3],[1767226200000,1.75]],"borderColor":"#a78bfa"},{"label":"Latency","legendGroup":"b","legendLabel":"Upstream B","axis":"latency","data":[[1767225600000,500],[1767225660000,450],[1767226200000,400]],"borderColor":"#c4b5fd"}]}`, Headers: []string{"UTC time", "A rate", "A latency", "B rate", "B latency"}, Rows: [][]string{{"00:00", "1.5 QPS", "300 us", "2 QPS", "500 us"}, {"00:01", "Unavailable", "350 us", "3 QPS", "450 us"}, {"00:10", "4.25 QPS", "500 us", "1.75 QPS", "400 us"}}},
		{ID: "histogram", Title: "Pre-binned response time", Description: "Bucket ranges are supplied by the consumer", Spec: `{"type":"bar","legend":{"show":false},"labels":["0-1 ms","1-5 ms","5-20 ms",">20 ms"],"bounds":["[0,1)","[1,5)","[5,20)","[20,infinity)"],"datasets":[{"label":"Samples","unit":"count","data":[12,30,8,1],"backgroundColor":"#58a6ff"}]}`, Headers: []string{"Bucket", "Samples"}, Rows: [][]string{{"0-1 ms", "12"}, {"1-5 ms", "30"}, {"5-20 ms", "8"}, {">20 ms", "1"}}},
		{ID: "percentiles", Title: "Percentile categories", Description: "Named percentile labels retain their order and units", Spec: `{"type":"line","legend":{"show":true},"labels":["p50","p95","p99"],"axes":[{"id":"latency","unit":"ms","precision":2}],"datasets":[{"label":"Upstream A","axis":"latency","data":[2.5,5,9],"borderColor":"#58a6ff"},{"label":"Upstream B","axis":"latency","data":[3,6,12],"borderColor":"#a78bfa"}]}`, Headers: []string{"Percentile", "A", "B"}, Rows: [][]string{{"p50", "2.5 ms", "3 ms"}, {"p95", "5 ms", "6 ms"}, {"p99", "9 ms", "12 ms"}}},
		{ID: "ranking", Title: "Horizontal ranking", Description: "First category stays at the top", Spec: `{"type":"bar","horizontal":true,"labels":["Group A","Group B","Group C"],"datasets":[{"label":"Requests","data":[12000,7000,3000],"backgroundColor":"#58a6ff"}]}`, Headers: []string{"Group", "Requests"}, Rows: [][]string{{"A", "12000"}, {"B", "7000"}, {"C", "3000"}}},
		{ID: "distribution", Title: "Distribution", Description: "Category colors and accessible table", Spec: `{"type":"doughnut","labels":["Completed","Waiting","Failed"],"datasets":[{"label":"Requests","data":[80,15,5],"backgroundColor":["#58a6ff","#fbbf24","#fb7185"]}]}`, Headers: []string{"Outcome", "Requests"}, Rows: [][]string{{"Completed", "80"}, {"Waiting", "15"}, {"Failed", "5"}}},
	}
}
